};

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream html;
    std::vector<std::string> lines;
    std::string line;

    // Split markdown into lines
    for (const auto& c : markdown) {
        if (c == '\n') {
            lines.emplace_back(line);
            line.clear();
        } else {
            line += c;
        }
    }
    if (!line.empty()) {
        lines.emplace_back(line);
    }

    // Convert each line to HTML
    for (const auto& line : lines) {
        std::string html_line;
        std::size_t pos = 0;

        // Apply Markdown to HTML conversion rules
        while ((pos = line.find_first_of(md2html_rules, pos)) != std::string::npos) {
            const auto& rule = md2html_rules.at(line.substr(pos, 2));
            html_line += line.substr(pos, 2);
            html_line += rule;
            pos += 2;
        }

